// Run against bindings generated by build.py --target nodejs.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {JavaScriptEngine}=require(path.resolve(process.argv[2]||'target/rustel-browser-audio-test/rustel_browser_audio.js'));
const logging=new JavaScriptEngine("console.log('hello console', {answer:42}); note('c4').s('sine')",48000,'{}');
assert.deepEqual(JSON.parse(logging.logs_json()),['hello console {"answer":42}']);
assert.deepEqual(JSON.parse(logging.logs_json()),[]);logging.free();
const reports=[];
for(const name of fs.readdirSync(path.join(__dirname,'../demos')).filter(n=>n.endsWith('.strudel'))){
 const source=fs.readFileSync(path.join(__dirname,'../demos',name),'utf8'),engine=new JavaScriptEngine(source,48000,'{}');
 const metadata=JSON.parse(engine.metadata_json()),probe=JSON.parse(engine.probe_json(0,4));assert.equal(metadata.source,source);assert(probe.length>0);assert(metadata.lanes.length>0);
 const sampleNeeds=probe.map(value=>engine.needs_sample(JSON.stringify(value)));
 let peak=0,events=0;const missing=new Set();
 for(let i=0;i<24;i++){for(const v of engine.render(4096)){assert(Number.isFinite(v));peak=Math.max(peak,Math.abs(v));}events+=JSON.parse(engine.events_json()).length;for(const value of JSON.parse(engine.missing_json()))missing.add(value.s||value.sound);}
 if(!sampleNeeds.some(Boolean)){assert(peak>0.001,name);assert(events>0,name);assert.equal(missing.size,0,name);}
 else{assert(missing.size>0,name);if(sampleNeeds.every(Boolean))assert.equal(peak,0,name);}// Missing samples stay missing, never replaced by oscillators; mixed arrangements may still emit synth voices.
 reports.push({name,lanes:metadata.lanes.length,queried:probe.length,peak,events,missing:[...missing]});engine.free();
}
// A sample-only score becomes audible only after installing actual host PCM.
const engine=new JavaScriptEngine('samples({fixture:["tone.wav"]}, "https://example.invalid/"); note("c3").s("fixture").gain(0.2)',48000,'{}');
assert.equal(JSON.parse(engine.metadata_json()).samples.length,1);assert(engine.needs_sample('{"s":"fixture","note":48}'));
const pcm=Float32Array.from({length:48000},(_,i)=>Math.sin(i*2*Math.PI*220/48000)*0.1),id=engine.install_pcm(48000,1,pcm);
engine.register_bank('fixture',JSON.stringify([{id,variant:0,variant_count:1,root:48,duration:1}]));assert(!engine.needs_sample('{"s":"fixture","note":48}'));
const output=engine.render(4096);assert(output.some(v=>Math.abs(v)>0.001));assert.equal(JSON.parse(engine.missing_json()).length,0);engine.free();
// Studio visual taps remain receiver-isolated, and orbit faders reach real DSP.
const visuals=new JavaScriptEngine('$: note("a3").s("sine").orbit(0).gain(.1)._scope()\n$: note("a5").s("sine").orbit(1).gain(.2)._scope()',48000,'{}');
visuals.set_visual_capture(true);visuals.render(4096);
const taps=JSON.parse(visuals.visual_audio_json());assert.equal(taps.length,2);
for(const tap of taps){assert.equal(tap.samples.length,4096);assert(tap.samples.some(v=>Math.abs(v)>.001));}
assert.notDeepEqual(taps[0].samples,taps[1].samples);
const masks=new Set(JSON.parse(visuals.events_json()).map(e=>e.ui_visuals));assert(masks.has('1')&&masks.has('2'));
visuals.set_orbit_gain(0,0);assert(visuals.render(4096).some(v=>Math.abs(v)>.001),"muting one orbit must leave its sibling audible");
visuals.set_orbit_gain(1,0);assert(visuals.render(4096).every(v=>Math.abs(v)<.00001));visuals.free();
for(const root of ['F','C']){
 const chords=['maj7','^7'].map(suffix=>{const e=new JavaScriptEngine(`chord("${root}${suffix}").dict("ireal").voicing().s("sine")`,48000,'{}');const notes=JSON.parse(e.probe_json(0,1)).map(v=>v.note);e.free();return notes;});
 assert(chords[0].length>0,'major-seventh alias must produce notes');assert.deepEqual(chords[0],chords[1]);
}
assert.throws(()=>new JavaScriptEngine('while(true){}',48000,'{}'));
// Visual declarations cannot create, silence or reorder emitting lanes.
const foxySource='$: note("c3").s("sine")._foxy()\n$: note("e4").s("triangle")\n_all_foxy({mode:"3d"})';
const foxes=new JavaScriptEngine(foxySource,48000,'{}');
assert.equal(JSON.parse(foxes.metadata_json()).lanes.length,2);
assert(foxes.render(4096).some(v=>Math.abs(v)>.001));
const foxEvents=JSON.parse(foxes.events_json());
assert(foxEvents.some(e=>e.lane==='#0'&&e.ui_visuals==='1'));
assert(foxEvents.some(e=>e.lane==='#1'&&e.ui_visuals==='0'));
foxes.free();
console.log(JSON.stringify({demos:reports,installedPcm:true,scoreEffects:true,runawayJavascriptRefused:true},null,2));
